import{_ as t,H as i,f as n,i as a}from"./chunks/framework.BH2BK_3i.js";const h=JSON.parse('{"title":"结束语 | 2025年度人物：我们，未来的AI架构师","description":"","frontmatter":{},"headers":[{"level":2,"title":"第一个问题： 我们应该怎样进一步学习？","slug":"第一个问题-我们应该怎样进一步学习","link":"#第一个问题-我们应该怎样进一步学习","children":[]},{"level":2,"title":"第二个问题：未来的 AI 软件工程师会在做什么？","slug":"第二个问题-未来的-ai-软件工程师会在做什么","link":"#第二个问题-未来的-ai-软件工程师会在做什么","children":[]}],"relativePath":"MCP&A2A前沿实战/结束语｜2025年度人物：我们，未来的AI架构师.md","filePath":"MCP&A2A前沿实战/结束语｜2025年度人物：我们，未来的AI架构师.md","lastUpdated":1795531178000}'),p={name:"MCP&A2A前沿实战/结束语｜2025年度人物：我们，未来的AI架构师.md"};function s(A,e,l,E,o,r){return i(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="结束语-2025年度人物-我们-未来的ai架构师" tabindex="-1">结束语 | 2025年度人物：我们，未来的AI架构师 <a class="header-anchor" href="#结束语-2025年度人物-我们-未来的ai架构师" aria-label="Permalink to &quot;结束语 | 2025年度人物：我们，未来的AI架构师&quot;">​</a></h1><p>你好。我是黄佳。</p><p>今天是 2025 年 12 月 13 日。听说北京已经迎来了冬天的第一场雪，而我所在的南国，依然是炎炎夏日。</p><p>无论我们是否生活在一个充满 AI 的世界里，大自然的轮回始终在提醒我们：时间在流动，季节在更替，生活自有它的节奏与味道。</p><p>故宫的雪景一如既往地美丽 —— 而且，它与世界上是否存在英伟达的芯片，毫无关系。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/1.png" alt=""></a></p><ul><li>永远爱故宫的雪</li></ul><p>今年，对我来说是收获满满的一年。希望你也是如此。</p><p>年初，正值 DeepSeek 的爆火，我推出了极客时间专栏《大模型 RAG 进阶训练营》，以及书籍《RAG 实战课》。从六月开始，我和编辑老师共同创作《MCP 和 A2A 前沿实战》，专栏一路更新到现在。</p><p>非常感谢你的陪伴。我想，是时候和大家暂时告别一下了。这是一个阶段性的告别，也是为2026 年新的专栏与思考，积蓄能量。</p><p>AI 时代，我们难免会有一点点焦虑。这个焦虑的核心来源是 AI 让世界变化太快——但我们人类其实从内心深处都有点抗拒改变，改变意味着未知，未知可能带来风险。当然也有可能带来机会。</p><p>结束语里我想和你讨论两个问题，从具体实操和宏观方向两个角度，聊一聊 AI 时代我们可以往哪个方向走。这两个问题可能曾经也浮现在你的脑海里，是当下的时刻比较应景且具有共性的。希望通过我的答案给你带来些许启发，</p><h2 id="第一个问题-我们应该怎样进一步学习" tabindex="-1">第一个问题： 我们应该怎样进一步学习？ <a class="header-anchor" href="#第一个问题-我们应该怎样进一步学习" aria-label="Permalink to &quot;第一个问题： 我们应该怎样进一步学习？&quot;">​</a></h2><p>这是我的好多读者都曾经问过我的问题。因为是我的读者，也许阅读过我的[《零基础学机器学习》《LangChain 实战课》《RAG 实战课》《MCP 和 A2A 前沿实战》等书籍或专栏，希望我的课程顺利帮你打通“入门通路”的作用… —— 但是，然后呢？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/2.png" alt=""></a></p><ul><li>师傅能带你快速入门，然后呢</li></ul><p>要通过几本书，几门课，真正成为专家，在职场呼风唤雨，成为 AI 领域资深架构师，项目的设计师，还差得远。那怎么办呢？AI 时代最不缺的就是各种各样的资料。但是资料太多反而带来了选择困难。</p><p>对这个非常实在的问题，我有非常具体和实在的答案：</p><p>我的答案可以概括为两条耳熟能详的传统谚语。</p><ol><li><p>师傅领进门，修行在个人。</p></li><li><p>学而时习之，不亦说乎。</p></li></ol><p>下面展开说说。</p><p>第一，要真正走上进阶之路，仅仅靠第二手的资料是行不通的。如同我在上面微信聊天记录中所展示的那样，一定要亲自跟进大厂的产品发布节奏和方法论。获取最新、最直接、最前沿的第一手信息，只有这样，才能让你在 AI 时代保持领先的优势。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/3.png" alt=""></a></p><ul><li>第一手资料永远最重要</li></ul><p>比如你要时不时地逛逛 Engineering at Antropic 这个页面，很多颠覆性的技术，如 MCP、Agent Skills、Context Caching 的思想，都发布自这里。等他们流行起来，等到你我听说的时候，其实 Anthropic 已经发布了好几个月了。在 AI 时代，领先别人几个月就学懂一个新技术是极大的优势。</p><p>除了 Anthropic 和 OpenAI 之外，Google Research, Reddit, Medium 等 AI 相关论坛、博客，都有可能是一手信息源。</p><p>关注一手信息，并不等于被信息洪流裹挟。</p><p>真正的进阶，不是每天刷更多链接，而是建立一个“跟进→实验→复盘→内化”的学习闭环。当你在 OpenAI、Google Research、Anthropic Engineering、Reddit、Medium、甚至 Twitter和微信公众号等地方看到一个新概念、新框架、新范式时，不要急着收藏或转发，而是立刻问自己三个问题：它解决了什么真实问题？我现有系统中哪个模块可以用它重构？如果让我用最小 Demo 复现，它的最小可行形态是什么？</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/4.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/4.png" alt=""></a></p><ul><li>新技术问世，直接去GithHub上下载代码跑起来（图中的 Agent Skills 就是 Anthropic 为 Agent 配备的最新武器）</li></ul><p>哪怕只花一两个晚上，把一个想法落成十几行代码、一个简化架构图、一段失败的实验记录，这个知识就已经从“别人的观点”变成了“你的能力”。长期来看，真正拉开差距的，从来不是你看过多少资料，而是你亲手验证、拆解、重构过多少次一线技术选择。这，才是从“学过 AI”走向“驾驭 AI”的那条进阶之路。</p><p>以上，也就是我所说的：学而时习之，不亦说乎 + 师傅领进门，修行在个人。</p><p>祝你在 AI 学习的道路上越走越深，越走越远，更重要的是能学以致用，把 AI 技术和你自己的工作实践、自身经验相结合，形成属于你自己的 AI 方法论。</p><p>这第一个问题是一个具体实操性质的问题，因此它是一个小问题。第二个问题是一个宏观问题，因此它是更大的问题。</p><h2 id="第二个问题-未来的-ai-软件工程师会在做什么" tabindex="-1">第二个问题：未来的 AI 软件工程师会在做什么？ <a class="header-anchor" href="#第二个问题-未来的-ai-软件工程师会在做什么" aria-label="Permalink to &quot;第二个问题：未来的 AI 软件工程师会在做什么？&quot;">​</a></h2><p>请你认真思考，AI 给我们的时代、我们的工作性质、我们的生活方式、我们的软件工程、我们的产品设计、我们的操作系统、我们的行为习惯带来了哪些改变？未来还会持续在哪些环节重塑，重构整个人类社会。</p><p>这是一个细思极恐的问题，但是也是一个必须思考的问题。</p><p>因为只有你头脑中有了对未来的方向性思考，你在知道自己应该学习什么，做什么，应该往哪个方向发展。—— 否则，再爱学习，再学而时习之，也有可能是白费苦工。</p><p>十年后，当现在的热词（Agent、RAG、LoRA、Vector DB）都变成像 “TCP/IP”一样虽然重要，但没人挂在嘴边的基础设施时，AI 工程师的日常工作大概率是：</p><ul><li><p>定义接口（类似写 MCP）：确保公司的数据能被 AI 读懂。</p></li><li><p>确立标准（类似写 Evals）：告诉系统什么是“好的结果”。</p></li><li><p>设计流程（类似画 LangGraph）：设计 AI 的思考路径和纠错机制。</p></li><li><p>审查技能（类似 Review Skills）：审核 AI 自己写出来的工具脚本是否安全。</p></li></ul><p>让我们把思绪从未来切回现在，AI 把很多东西简单化了，但是它提高了工程师未来的胜任力门槛。希望你在惊叹 AI 助手帮你释放了不少生产力之外，意识到 AI 给我们的时间不是白给的，我们空闲出来的时间必须去重新塑造我们的价值。</p><p>在人机协作的过程中，我们并不是跟 AI 去比较代码写得多快，而是去比我们能够思考到多深。工具、框架会不断演进、大浪淘沙，未来所用的工具并不是我们今天所看到的，留下来的是“如何管理和约束 AI 系统不确定性，使其产出确定性价值”的方法论。</p><p>——上面只是我的答案，也期待你在评论区分享你自己的思考。</p><p>最后，我想——技术会过时，模型会迭代，但系统性的架构思维，将是你穿越 AI 周期最坚实的船票。</p><p>我是黄佳。感谢你这几个月来的陪伴。如果你在这个专栏中有所收获，无论是知识的增加，代码和架构能力的提升，还是认知视野的开阔，我都倍感荣幸。请记住：Agent 的时代才刚刚开始，而你是第一批手握蓝图的建筑师。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/5.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/5.png" alt=""></a></p><ul><li>时代杂志的2025年度人物是马斯克、黄仁勋、奥尔特曼等AI的架构师们，我们当然也是其中的一部分——未来的AI架构师</li></ul><p>最后，希望你可以花几分钟时间填一下结课问卷，和我分享你对这门课的建议、想法，我会认真参考你的反馈！</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/6.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/MCP%26A2A%E5%89%8D%E6%B2%BF%E5%AE%9E%E6%88%98/images/%25E7%25BB%2593%25E6%259D%259F%25E8%25AF%25AD/6.png" alt=""></a></p><p>让我们在 2026 年的新一个技术浪潮中再见！</p>',50)])])}const c=t(p,[["render",s]]);export{h as __pageData,c as default};
